select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_edition_id":"OL42854732M"},"seq":1,"relation":"editions","after_row":{"id":987205005,"title":"De mistmonsters","isbn_10":null,"isbn_13":"9789010018052","work_id":987105001,"cover_id":null,"language":"dut","publisher":"Elsevier","publish_date":null,"open_library_edition_id":"OL42854732M"},"before_row":null},{"key":{"work_id":987105001,"language":"nl"},"seq":2,"relation":"catalog_work_descriptions","after_row":{"text":"Een Arabische reiziger uit de tiende eeuw trekt met een groep Vikingen naar hun nederzetting. Zijn waarnemingen van een onbekende cultuur vormen het begin van een tocht die steeds verder het gebied van angst en verbeelding binnengaat. Michael Crichton verbindt in deze roman een historische reisbeschrijving met motieven uit Beowulf. Het resultaat krijgt de vorm van een oud verslag, maar blijft fictie. De ontmoeting tussen verschillende werelden staat centraal in het avontuur dat zich ontvouwt.","work_id":987105001,"evidence":[{"note":"De mistmonsters is Dutch Eaters of the Dead1976, not a movie novelisation or an edition of Beowulf. Exact KB1977Elsevier paperback9789010018052; narrator manuscript framing remains fiction. Existing Work282 retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801872723"],"reference":"work:282","checked_at":"2026-11-02T18:09:00.000Z","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://openlibrary.org/works/OL46873W","https://data.bibliotheken.nl/id/nbt/p801872723"]},{"type":"cover_front_review","sha256":"33920e87c8dc824784d96a2e18a13d7827a777d4fc043bc44f03c99b984deef9","cover_id":13015524,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL46873W","reviewed_at":"2026-11-02T18:09:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-006","review_status":"approved","bound_author_id":987304002},"before_row":null},{"key":{"edition_id":987205005},"seq":3,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987105001,"evidence":[{"note":"De mistmonsters is Dutch Eaters of the Dead1976, not a movie novelisation or an edition of Beowulf. Exact KB1977Elsevier paperback9789010018052; narrator manuscript framing remains fiction. Existing Work282 retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801872723"],"reference":"work:282","checked_at":"2026-11-02T18:09:00.000Z","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://openlibrary.org/works/OL46873W","https://data.bibliotheken.nl/id/nbt/p801872723"]},{"type":"cover_front_review","sha256":"33920e87c8dc824784d96a2e18a13d7827a777d4fc043bc44f03c99b984deef9","cover_id":13015524,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13015524-L.jpg?default=false","edition_id":987205005,"bound_title":"De mistmonsters","reviewed_at":"2026-11-02T18:09:00+00:00","bound_isbn13":"9789010018052","evidence_url":"https://data.bibliotheken.nl/id/nbt/p801872723","review_batch":"nl-scale-20261102-006","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13015524-M.jpg?default=false","bound_author_id":987304002},"before_row":null},{"key":{"open_library_edition_id":"OL61374864M"},"seq":4,"relation":"editions","after_row":{"id":987205006,"title":"De chirurg","isbn_10":null,"isbn_13":"9789044358490","work_id":987105003,"cover_id":null,"language":"dut","publisher":"The House of Books","publish_date":null,"open_library_edition_id":"OL61374864M"},"before_row":null},{"key":{"work_id":987105003,"language":"nl"},"seq":5,"relation":"catalog_work_descriptions","after_row":{"text":"In Boston worden vrouwen vermoord door iemand die over opvallende medische kennis lijkt te beschikken. Rechercheurs Thomas Moore en Jane Rizzoli zoeken naar het verband tussen de slachtoffers. Hun onderzoek leidt naar arts Catherine Cordell, die eerder een gewelddadige aanval overleefde. De nieuwe dader lijkt haar verleden te kennen en richt zijn aandacht op haar. De politie moet uitzoeken hoe die kennis mogelijk is en voorkomen dat een vroegere bedreiging in een andere vorm terugkeert.","work_id":987105003,"evidence":[{"note":"Exact2019Dutch paperback9789044358490 is independently listed by Bibliotheek. Prefer its verified334x500cover over enlarging the older2009printing131x200cover. Existing Surgeon2001Work retained; Christine Marshall is not the author.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p42284117X"],"reference":"work:607","checked_at":"2026-11-02T18:09:00.000Z","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-019.json","sources":["https://www.bibliotheek.nl/catalogus/titel.412356724.html/de-chirurg/","https://openlibrary.org/works/OL14871640W","https://data.bibliotheken.nl/id/nbt/p42284117X"]},{"type":"cover_front_review","sha256":"ec5451d33d562d0591d263f0c644254332283b0d6659526ea4c5981b41c994f5","cover_id":15174409,"reference":"cover-semantic-review-007.json","limitation":"Front Tess Gerritsen, De Chirurg, House of Books logo and sink/blood design. Same source2019Dutch paperbackISBN9789044358490 independently corroborated by Bibliotheek exactprinting. Prefer this334x500cover to enlarging older131x200printing image. Front does not show ISBN barcode."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.bibliotheek.nl/catalogus/titel.412