ult=false","bound_author_id":987305001},"before_row":null},{"key":{"id":987105002},"seq":7,"relation":"works","after_row":{"id":987105002,"title":"Honeymoon","cover_id":null,"author_id":946300342,"work_type":null,"source_type":"open_library","open_library_id":"OL167160W","first_publish_year":2005,"native_identity_key":"nlscale:fixture006:562"},"before_row":{"id":987105002,"title":"Honeymoon","cover_id":null,"author_id":946300342,"work_type":null,"source_type":"open_library","open_library_id":"OL167160W","first_publish_year":2001,"native_identity_key":"nlscale:fixture006:562"}},{"key":{"open_library_edition_id":"OL47139245M"},"seq":8,"relation":"editions","after_row":{"id":987205007,"title":"Belofte maakt schuld","isbn_10":null,"isbn_13":"9789046113677","work_id":987105002,"cover_id":null,"language":"dut","publisher":"Zwarte Beertjes","publish_date":null,"open_library_edition_id":"OL47139245M"},"before_row":null},{"key":{"work_id":987105002,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"Nora Sinclair lijkt een leven te leiden dat weinig te wensen overlaat. Toch gebeuren er rond haar verontrustende dingen, vooral met de mannen die dichtbij haar komen. FBI-agent John O''Hara probeert vast te stellen of er een verband bestaat. Naarmate hij meer tijd met haar doorbrengt, raakt zijn onderzoek vermengd met persoonlijke aantrekkingskracht. Hij moet bepalen of de onduidelijkheden in haar verleden aanwijzingen vormen of dat zijn eigen gevoelens zijn oordeel beginnen te beïnvloeden.","work_id":987105002,"evidence":[{"note":"Honeymoon originally1February2005 by James Patterson and Howard Roughan. Dutch Belofte maakt schuld9789046113677 is same novel. Copyright2004/current2001 do not establish original first release.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p320421716"],"reference":"work:562","checked_at":"2026-11-02T18:09:00.000Z","supplemental":null},{"type":"original_substantive_source_re