34-L.jpg?default=false","edition_id":987205007,"bound_title":"Belofte maakt schuld","reviewed_at":"2026-11-02T18:09:00+00:00","bound_isbn13":"9789046113677","evidence_url":"https://data.bibliotheken.nl/id/nbt/p320421716","review_batch":"nl-scale-20261102-006","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13536434-M.jpg?default=false","bound_author_id":946300342},"before_row":null},{"key":{"id":987205004},"seq":11,"relation":"editions","after_row":{"id":987205004,"title":"Judy Moody Geliyor 1","isbn_10":"6054482548","isbn_13":"9786054482542","work_id":987105004,"cover_id":null,"language":"tur","publisher":"Artemis Yaynlar","publish_date":null,"open_library_edition_id":"OL35611866M"},"before_row":{"id":987205004,"title":"Judy Moody Geliyor 1","isbn_10":"6054482548","isbn_13":"9786054482542","work_id":987105004,"cover_id":null,"language":"dut","publisher":"Artemis Yaynlar","publish_date":null,"open_library_edition_id":"OL35611866M"}},{"key":{"isbn_13":"9789026997501"},"seq":12,"relation":"editions","after_row":{"id":987205008,"title":"Fleur Humeur","isbn_10":null,"isbn_13":"9789026997501","work_id":987105004,"cover_id":null,"language":"dut","publisher":"Van Holkema & Warendorf","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"work_id":987105004,"language":"nl"},"seq":13,"relation":"catalog_work_descriptions","after_row":{"text":"Fleur heeft na de vakantie weinig zin om weer naar school te gaan. Haar humeur verandert gemakkelijk en de mensen om haar heen merken dat. Wanneer de klas een collage moet maken die laat zien wie ieder kind is, begint ze materiaal uit haar eigen leven te verzamelen. Gewone gebeurtenissen thuis en op school krijgen daardoor een andere betekenis. Megan McDonald vertelt vanuit een kind dat haar plaats tussen familie en klasgenoten probeert te vinden en niet altijd weet hoe zij zich daarbij voelt.","work_id":987105004,"evidence":[{"note":"Fleur Humeur is the first full Judy Moody novel, not Fleur wordt beroemd. Repair Turkish current5813dut→tur and add independently bibliographically identified Dutch hardcover. Operational net0 because old erroneous dut counted as available.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p255790708","http://data.bibliotheken.nl/id/nbt/p265792169"],"reference":"work:5654","checked_at":"2026-11-02T18:09:00.000Z","supplemental":{"review":"focused-source-readings-006.json","exactIsbn10":"9026997507","formatSource":"https://www.bol.com/be/fr/p/fleur-humeur/1001004001986292/"}},{"type":"original_substantive_source_review","review":"content-amendment-005.json","sources":["https://www.nbdbiblion.nl/sites/nbdbiblion.nl/files/Onderwijsrecensie-PO-editie3.pdf","https://www.dbnl.org/tekst/_lee023200401_01/_lee023200401_01_0012.php","https://www.bol.com/be/fr/p/fleur-humeur/1001004001986292/","https://openlibrary.org/works/OL443606W","https://data.bibliotheken.nl/id/nbt/p255790708","https://data.bibliotheken.nl/id/nbt/p265792169"]},{"type":"cover_front_review","sha256":"8e5870040f8eca855f3a469b547cad1eee1724fcad57091974b38c8f34c25245","cover_id":11396758,"reference":"cover-semantic-review-007.json","limitation":"Orange front Megan McDonald, Fleur Humeur, Met illustraties van Peter Reynolds. Correct Dutch first Judy Moody novel, not Turkish Geliyor or Fleur wordt beroemd. OL record combines two printingISBNs; front confirms title/credits, exact printing remains separately bound by KB and merchant evidence, not image alone."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.nbdbiblion.nl/sites/nbdbiblion.nl/files/Onderwijsrecensie-PO-editie3.pdf","reviewed_at":"2026-11-02T18:09:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-006","review_status":"approved","bound_author_id":987305002},"before_row":null},{"key":{"edition_id":987205008